def find_2_lines_v2(grid):
    """Find horizontal and vertical 2-lines, tolerating 3-shape interruptions"""
    rows = len(grid)
    cols = len(grid[0])
    h_lines = set()  # rows that are all 2s
    v_lines = set()  # cols where most/all are 2s

    for r in range(rows):
        if all(grid[r][c] == 2 for c in range(cols)):
            h_lines.add(r)

    # For vertical lines, check each col for "enough" 2s but not ALL (to handle interruptions)
    for c in range(cols):
        two_count = sum(1 for r in range(rows) if grid[r][c] == 2)
        # Must have at least 5 consecutive 2s or be very close to complete (minus a few for 3-shape)
        if two_count >= max(5, rows - 2):
            v_lines.add(c)

    return h_lines, v_lines

def get_2_line_cells(grid, v_lines, rows, cols):
    """Get all 2-line cells"""
    cells = set()
    for c in v_lines:
        for r in range(rows):
            cells.add((r, c))
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                cells.add((r, c))
    return cells

