def find_3_shapes_v2(grid):
    """Find shapes of 3s around an intersection point"""
    rows = len(grid)
    cols = len(grid[0])
    shapes = []

    # Look for patterns where a 3x block has 3s and possibly a 2 at center
    for r in range(rows - 1):  # Can have 2 rows of 3s
        for c in range(cols - 1):  # Can have 2 cols of 3s
            # Check for vertical bar of 3s
            if r <= 1 and c <= 1:
                continue

            # Look for 3-shape: 2 rows by 3 cols or 3 rows by 2 cols with 3s
            # More flexible pattern: find regions of 3s with dense packing

            # Simplest: check for plus shape
            plus_3s = []
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] == 3:
                            plus_3s.append((nr, nc))

            # If we have 8 3s around center (r+1, c+1), it's a 3-shape
            if len(plus_3s) == 5 and (r+1, c+1) not in plus_3s:  # Plus pattern
                center_val = grid[r+1][c+1]
                shapes.append((r, c, r+1, c+1, center_val))

    # Another pattern: 3 rows with 3s in center 3 columns
    for r in range(rows - 2):
        for c in range(cols - 2):
            block_cells = []
            for dr in range(3):
                for dc in range(3):
                    block_cells.append(grid[r+dr][c+dc])
            # If at least 7 cells are 3 (or some 3s with center being 2)
            plus_s_count = sum(1 for x in block_cells if x == 3)
            if plus_s_count >= 8 or (plus_s_count >= 7 and any(x == 2 for x in block_cells)):
                center_r, center_c = r + 1, c + 1
                center_val = grid[center_r][center_c]
                shapes.append((center_r, center_c, plus_s_count, center_val))

    return shapes

